import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        Map<String, Integer> visits = new TreeMap<>();

        String line;
        while ((line = br.readLine()) != null) {
            if (line.isBlank()) {
                continue;
            }
            String name = line.strip().toLowerCase();
            visits.put(name, visits.getOrDefault(name, 0) + 1);
        }

        Set<String> repeats = new TreeSet<>();
        for (Map.Entry<String, Integer> entry : visits.entrySet()) {
            int count = entry.getValue();
            if (count > 1) {
                repeats.add(entry.getKey());
            }
        }
        System.out.println("Unique visitors: " + visits.size());
        System.out.println("Repeat visitors: " + repeats);
    }
}

