import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().strip());

        List<Product> products = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().strip().split("\\s+");
            products.add(new Product(parts[0], parts[1], Double.parseDouble(parts[2])));
        }

        products.sort(Comparator.comparing(Product::getCategory)
                .thenComparingDouble(Product::getPrice)
                .thenComparing(Product::getName));
        for (Product p : products) {
            System.out.println(p);
        }
    }
}

class Product {
    private final String name;
    private final String category;
    private final double price;

    public Product(String name, String category, double price) {
        this.name = name;
        this.category = category;
        this.price = price;
    }

    public String getName() {
        return name;
    }

    public String getCategory() {
        return category;
    }

    public double getPrice() {
        return price;
    }

    @Override
    public String toString() {
        return "%s: %s %.2f".formatted(category, name, price);
    }
}
